// Pseudo-code illustrating a PCAmix-like pipeline
const numericCols = [...];
const catCols = [...];
function preprocess(x){
  const n = medianImpute(x[numericCols]);
  const c = modeImpute(x[catCols]);
  const nScaled = scale(n);
  const cEncoded = oneHotEncode(c);
  return concat(nScaled, cEncoded);
}
const pca = new PCAMix({nComponents:6, global: true});
const z = pca.fitTransform(dataset.map(preprocess));
